import Foundation

/// Emoji shortcodes, `:tada:` drawn as 🎉 (PLAN.md §M39 ▸ Slice 6).
///
/// The names are GitHub's, from gemoji (`MarkdownEmojiTable.swift`, generated by
/// `scripts/generate_emoji_shortcodes.py`), and so is the rule for where one is read. GitHub's rule
/// is written down nowhere, so it was taken from GitHub's own renderer (its `/markdown` API,
/// 2026-11-13), and it is stranger than a word boundary:
///
/// - It works on one **run of text**, which is what an HTML text node is: the text between two
///   elements, soft breaks included. Emphasis, a code span, a link or a hard break ends a run.
/// - A **candidate** is `:` + letters, digits, `_`, `+` or `-` + `:`, found left to right without
///   overlapping. Upper case counts as a candidate even though no name has any (`:Smile:` is not
///   drawn), because a candidate is shaped by the scan, and only the table decides what is drawn.
/// - Only the run's **first** candidate's position matters. If it opens the run or follows
///   whitespace, every candidate in the run that names an emoji is drawn, wherever it sits:
///   `:smile: a:b:c` draws `a🅱️c`. If it follows anything else, nothing in the run is drawn:
///   `10:30:00 :smile:` stays text, because `:30:` came first.
///
/// That is also what keeps a Swift selector in prose readable: in `requestOpenLink(source:link:)`
/// the first candidate, `:link:`, follows a letter, where a plain search for known names turned it
/// into `source🔗`. Anything may follow a shortcode (`:smile:a` draws), and back-to-back ones need
/// nothing between them (`:+1::+1:`).
///
/// Drawn when the page is rendered, never in the parse. A heading's anchor is its text as written,
/// so `## :bulb: Highlights` draws 💡 and anchors as `#bulb-highlights`, which is what GitHub gave
/// that heading. An image's `alt` keeps its shortcode as well, as GitHub's does.
enum MarkdownEmoji {
    /// Every shortcode, read once from the generated source on first use.
    static let table: [String: String] = {
        var table: [String: String] = [:]
        table.reserveCapacity(tableCount)
        var name: Substring?
        for token in tableSource.split(whereSeparator: \.isWhitespace) {
            if let pending = name {
                table[String(pending)] = String(token)
                name = nil
            } else {
                name = token
            }
        }
        return table
    }()

    /// One run of text with its shortcodes drawn, or the same text when the rule draws none.
    static func converting(_ run: String) -> String {
        // The common cases, a run with no colon or with no `:name:` shape, cost one pass over its
        // bytes and no copy. A candidate in characters is always one in bytes too, so the bytes can
        // only let a run through that the characters then turn down.
        guard mayHoldCandidate(run.utf8) else { return run }
        let characters = Array(run)
        let candidates = candidates(in: characters)
        guard let first = candidates.first,
              first.lowerBound == 0 || isRunWhitespace(characters[first.lowerBound - 1])
        else { return run }
        var output = ""
        output.reserveCapacity(run.utf8.count)
        var cursor = 0
        for candidate in candidates {
            let name = String(characters[(candidate.lowerBound + 1)..<(candidate.upperBound - 1)])
            guard let emoji = table[name] else { continue }
            output.append(contentsOf: characters[cursor..<candidate.lowerBound])
            output.append(emoji)
            cursor = candidate.upperBound
        }
        guard cursor > 0 else { return run }
        output.append(contentsOf: characters[cursor...])
        return output
    }

    /// Each `:name:`-shaped stretch, colons included, left to right and never overlapping.
    private static func candidates(in characters: [Character]) -> [Range<Int>] {
        var found: [Range<Int>] = []
        var index = 0
        while index < characters.count {
            guard characters[index] == ":" else {
                index += 1
                continue
            }
            var end = index + 1
            while end < characters.count, isNameCharacter(characters[end]) {
                end += 1
            }
            if end > index + 1, end < characters.count, characters[end] == ":" {
                found.append(index..<(end + 1))
                index = end + 1
            } else {
                index += 1
            }
        }
        return found
    }

    /// Whether the bytes hold `:` + name bytes + `:` anywhere: the cheap test ahead of the real one.
    /// Measured over the 27 756 Markdown files on this Mac, the shortcode pass cost 5–7 % of the
    /// whole render without it, since most runs that hold a colon hold no candidate.
    private static func mayHoldCandidate(_ bytes: String.UTF8View) -> Bool {
        var nameLength: Int?
        for byte in bytes {
            if byte == UInt8(ascii: ":") {
                if let length = nameLength, length > 0 { return true }
                nameLength = 0
            } else if let length = nameLength {
                nameLength = isNameByte(byte) ? length + 1 : nil
            }
        }
        return false
    }

    /// ASCII letters and digits, `_`, `+` and `-`.
    private static func isNameCharacter(_ character: Character) -> Bool {
        character.asciiValue.map(isNameByte) ?? false
    }

    private static func isNameByte(_ byte: UInt8) -> Bool {
        switch byte {
        case UInt8(ascii: "a")...UInt8(ascii: "z"), UInt8(ascii: "A")...UInt8(ascii: "Z"),
             UInt8(ascii: "0")...UInt8(ascii: "9"), UInt8(ascii: "_"), UInt8(ascii: "+"),
             UInt8(ascii: "-"):
            true
        default:
            false
        }
    }

    /// ASCII whitespace only (tab through carriage return, and space): a no-break space before a
    /// shortcode leaves it as text on GitHub.
    private static func isRunWhitespace(_ character: Character) -> Bool {
        character.isASCII && character.isWhitespace
    }
}
